INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(35143, 'koKR', 'Krwawe elfy ze Srebrnej Luny wiwatują na cześć $n.', 'Krwawe elfy ze Srebrnej Luny wiwatują na cześć $n.', 0),
(35149, 'koKR', 'Orkowie z Orgrimmaru wiwatują na cześć $n.', 'Orkowie z Orgrimmaru wiwatują na cześć $n.', 0),
(35150, 'koKR', 'Taurenowie z Gromowych Urwisk wiwatują na cześć $n.', 'Taurenowie z Gromowych Urwisk wiwatują na cześć $n.', 0),
(35151, 'koKR', 'Trolle z Wioski Sen\'jin zaczynają śpiewać na cześć $n.', 'Trolle z Wioski Sen\'jin zaczynają śpiewać na cześć $n.', 0),
(35152, 'koKR', 'Porzuceni z Podmiasta wiwatują na cześć $n.', 'Porzuceni z Podmiasta wiwatują na cześć $n.', 0),
(35162, 'koKR', 'Widzowie z Hordy wiwatują na cześć $n.', 'Widzowie z Hordy wiwatują na cześć $n.', 0),
(35245, 'koKR', 'Dumny i silny – wiwat na cześć marszałka Jacoba Aleriusa, Wielkiego czempiona Wichrogrodu!', '', 0),
(35246, 'koKR', 'Potęgę krasnoludów reprezentuje dziś Wielka czempionka Żelaznej Kuźni, Lana Mocnomłot!', '', 0),
(35247, 'koKR', 'Z bramy wyłania się Colosos, górujący nad wszystkimi Wielki czempion Exodaru!', '', 0),
(35248, 'koKR', 'A oto nadchodzi mały, lecz zabójczy Ambrose Iskrobełt, Wielki czempion Gnomoregan!', '', 0),
(35249, 'koKR', 'Na arenę wkracza Wielka czempionka Darnassus, wprawna strażniczka Jaelyne Wieczorna Pieśń!', '', 0),
(35260, 'koKR', 'Słońcobójcy z dumą przedstawiają swoich reprezentantów w tej próbie walki.', '', 0),
(35319, 'koKR', 'Czy jesteś $ggotów:gotowa; na pierwsze wyzwanie, $N?', '', 0),
(35320, 'koKR', 'Jestem $ggotów:gotowa;.', 'Jestem $ggotów:gotowa;.', 0),
(35321, 'koKR', 'Witajcie, czempioni. Dziś, na oczach waszych przywódców i towarzyszy, udowodnicie, że jesteście godnymi wojownikami.', '', 0),
(35330, 'koKR', 'Najpierw zmierzycie się z trojgiem Wielkich Czempionów Turnieju! Ci zawzięci zawodnicy pokonali wszystkich innych i wspięli się na szczyt mistrzostwa w walce na kopie.', '', 0),
(35331, 'koKR', 'Zaczynajcie!', '', 0),
(35536, 'koKR', 'To był imponujący pokaz. Ale czy jesteście gotowi na kolejne wyzwanie?', '', 0),
(35537, 'koKR', 'Zaimponowaliście dziś wszystkim swoimi umiejętnościami na arenie. Nadszedł czas, by wszyscy uznali was za czempionów turnieju.', '', 0),
(35538, 'koKR', 'Jestem $ggotów:gotowa; na kolejne wyzwanie.', 'Jestem $ggotów:gotowa; na kolejne wyzwanie.', 0),
(35541, 'koKR', 'Dobra walka! Kolejne wyzwanie pochodzi z szeregów samej Krucjaty. Zmierzycie się z jej niemałym kunsztem.', '', 0),
(35542, 'koKR', 'Na arenę wkracza paladyn, któremu nie są obce ani pole bitwy, ani turniejowe szranki – Wielki czempion Krucjaty Argentu, Eadric Czysty!', '', 0),
(35543, 'koKR', 'Kolejna zawodniczka nie ma sobie równych w zapale do strzeżenia Światłości. Oto Spowiedniczka Argentu Paletress!', '', 0),
(35544, 'koKR', 'Dobra robota. Dziś udowodniliście swoją wartość...', '', 0),
(35545, 'koKR', 'Co to tam, pod belkami stropu?', '', 0),
(35547, 'koKR', 'Co to ma znaczyć?', '', 0),
(35677, 'koKR', 'Możecie zaczynać!', '', 0),
(36657, 'koKR', 'Jestem $ggotów:gotowa;. Ale pomińmy ceremonie.', 'Jestem $ggotów:gotowa;. Ale pomińmy ceremonie.', 0);
